    if(action==='voice-note'){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech)return toast('Voice dictation is not supported by this browser.');const area=$('#note-form textarea',root),recognition=new Speech();recognition.lang=navigator.language||'en-US';recognition.interimResults=false;recognition.onresult=event=>{area.value=`${area.value}${area.value?' ':''}${event.results[0][0].transcript}`};recognition.onerror=()=>toast('Could not access voice dictation. Check browser microphone permission.');recognition.onend=()=>toast('Dictation finished. Review the text before saving.');recognition.start();toast('Listening. Speak your note.');return}
