    if(action==='flashcard-create'){const quote=state.quotes.find(x=>x.id===id);if(!quote)return;if(state.flashcards.some(x=>x.quoteId===id))return toast('That highlight already has a study card.');state.flashcards.push({id:uid(),quoteId:id,bookId:quote.bookId,front:quote.comment||'What does this passage mean to you?',back:quote.text,dueDate:today(),intervalDays:0,reviews:0});await persist();render();toast('Study card created from your highlight.');return}
    if(action==='flashcard-reveal'){revealedCard=id;render();return}
    if(action==='flashcard-rate'){const card=state.flashcards.find(x=>x.id===id);if(card){Object.assign(card,rateFlashcard(card,button.dataset.rating,today()));revealedCard='';await persist();render();toast(`Next review scheduled for ${fmtDayMonth(card.dueDate)}.`)}return}
    if(action==='library-card-delete'){state.libraryCards=state.libraryCards.filter(x=>x.id!==id);await persist();render();toast('Library card removed.');return}
    if(action==='export-calendar'){if(!state.books.some(b=>b.plan?.days?.length))return toast('Make a reading plan first.');await download(`reading-calendar-${today()}.ics`,plansToICS(state.books,today()),'text/calendar;charset=utf-8');toast('Calendar file ready to import.');return}
    if(action==='export-markdown'){await download(`reading-notes-${today()}.md`,markdownArchive(state),'text/markdown;charset=utf-8');toast('Markdown archive saved.');return}
    if(action==='export-weekly'){const d=weeklyDigest(state.sessions,state.books,today());const report=`# Reading week · ${d.from} to ${d.to}\n\n- Pages: ${d.pages}\n- Reading time: ${d.minutes} minutes\n- Sessions: ${d.sessions}\n- Days read: ${d.days} of 7\n- Most read: ${d.topBook||'—'}\n`;await download(`reading-week-${today()}.md`,report,'text/markdown;charset=utf-8');toast('Weekly recap saved.');return}
    if(action==='timer-preset'){if(timerStart)return toast('Pause the timer before changing its length.');timerPreset=clamp(button.dataset.minutes,0,90);timerGoal=timerPreset*60;elapsed=0;timerComplete=false;timerBreak=false;render();return}
    if(action==='timer-break-start'){timerBreak=true;timerComplete=false;timerGoal=5*60;elapsed=0;timerStart=Date.now();clearInterval(timerInterval);timerInterval=setInterval(updateClock,1000);render();toast('Five-minute break started.');return}
    if(action==='timer-break-resume'){if(!timerBreak)return;timerStart=Date.now();clearInterval(timerInterval);timerInterval=setInterval(updateClock,1000);render();return}
    if(action==='timer-break-stop'){timerStart=0;elapsed=0;timerGoal=0;timerBreak=false;timerComplete=false;clearInterval(timerInterval);render();return}
    if(action==='timer-start'||action==='timer-resume'){if($('#timer-book',root)?.value)timerBook=$('#timer-book',root).value;if(!timerBook)timerBook=state.books.find(b=>b.status==='reading')?.id||state.books[0]?.id||'';if(!timerBook)return toast('Add a book before starting a timer.');timerBreak=false;timerComplete=false;timerGoal=timerPreset*60;timerStart=Date.now();clearInterval(timerInterval);timerInterval=setInterval(updateClock,1000);render();return}
